def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    minimal = []
    for cls in classes:
        if cls not in seen:
            seen.add(cls)
            minimal.append(cls)
            seen.update(cls.__mro__[1:-1])  # Exclude the class itself and object
    return minimal

