def _validate_labels(labels):
    import re
    from collections.abc import Hashable

    key_regex = re.compile(r'^[a-zA-Z0-9_.\-]+$')
    value_regex = re.compile(r'^[a-zA-Z0-9_.\-]+$')
    errors = []

    for key, value in labels.items():
        if not isinstance(key, Hashable):
            errors.append({str(key): 'expected hashable type'})
            continue
        if not isinstance(key, str):
            errors.append({str(key): 'expected string type for label key'})
        elif not key_regex.match(key):
            errors.append({key: f"Label key '{key}' does not match the regex '{key_regex.pattern}'"})

        if not isinstance(value, str):
            errors.append({str(value): 'expected string type for label value'})
        elif not value_regex.match(value):
            errors.append({value: f"Label value '{value}' does not match the regex '{value_regex.pattern}'"})

    if errors:
        raise ValidationError(messages=errors)

