def pretty(self, indent=0, debug=False):
    """
    Return a pretty formatted representation of self.
    """
    ind = ' ' * indent
    result = f"{ind}{self.__class__.__name__}(\n"
    for key, value in self.__dict__.items():
        if isinstance(value, str):
            value = f"'{value}'"
        elif hasattr(value, 'pretty'):
            value = value.pretty(indent + 2, debug)
        elif isinstance(value, list):
            value = '[\n' + ',\n'.join([v.pretty(indent + 2, debug) if hasattr(v, 'pretty') else str(v) for v in value]) + '\n' + ind + ']'
        result += f"{ind}  {key}={value},\n"
    result += ind + ')'
    return result

