def deep_merge_nodes(nodes):
    from collections import defaultdict

    merged_dict = defaultdict(lambda: None)

    def merge_key_value(key, value):
        if key in merged_dict:
            if isinstance(merged_dict[key], MappingNode) and isinstance(value, MappingNode):
                merged_children = {}
                existing_children = {child[0].value: child[1] for child in merged_dict[key].value}
                new_children = {child[0].value: child[1] for child in value.value}
                for k in set(existing_children) | set(new_children):
                    if k in existing_children and k in new_children:
                        merge_key_value(existing_children[k], new_children[k])
                    elif k in existing_children:
                        merge_key_value(existing_children[k], existing_children[k])
                    else:
                        merge_key_value(new_children[k], new_children[k])
                merged_dict[key].value = list(merged_children.items())
            else:
                merged_dict[key] = value
        else:
            merged_dict[key] = value

    for key_node, value_node in nodes:
        merge_key_value(key_node, value_node)

    return list(merged_dict.items())

