def deep_merge_nodes(nodes):
    from collections import defaultdict

    merged = defaultdict(lambda: (None, None))

    for key_node, value_node in nodes:
        key = key_node.value
        if isinstance(value_node, ruamel.yaml.nodes.MappingNode):
            if merged[key][0] is None:
                merged[key] = (key_node, value_node)
            else:
                existing_key_node, existing_value_node = merged[key]
                existing_value_dict = dict(existing_value_node.value)
                for new_key_node, new_value_node in value_node.value:
                    existing_value_dict[new_key_node.value] = (new_key_node, new_value_node)
                existing_value_node.value = list(existing_value_dict.values())
        else:
            merged[key] = (key_node, value_node)

    return list(merged.values())

