def _verify(iface, candidate, tentative=False, vtype=None):
    errors = []
    if not tentative and not iface.providedBy(candidate):
        errors.append(f"Candidate does not provide the interface {iface}")

    required_methods = set(iface.names(True))
    candidate_methods = set(dir(candidate))
    missing_methods = required_methods - candidate_methods
    if missing_methods:
        errors.extend(f"Method {method} is not defined" for method in missing_methods)

    for method_name in required_methods:
        if method_name in candidate_methods:
            method = getattr(candidate, method_name)
            if not callable(method):
                errors.append(f"Attribute {method_name} is not callable")
            else:
                method_signature = inspect.signature(method)
                iface_method_signature = iface[method_name].getSignatureInfo().get('required', [])
                if len(method_signature.parameters) != len(iface_method_signature):
                    errors.append(f"Method {method_name} has incorrect signature")

    required_attributes = set(attr for name, attr in iface.namesAndDescriptions() if not IMethod.providedBy(attr))
    missing_attributes = required_attributes - set(getattr(candidate, attr, None) for attr in required_attributes)
    if missing_attributes:
        errors.extend(f"Attribute {attr} is not defined" for attr in required_attributes)

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid("\n".join(errors))
    return True

def verifyObject(iface, candidate, tentative=False):
    errors = []

    if not tentative:
        if not iface.providedBy(candidate):
            errors.append(f"Candidate does not provide the interface {iface}")

    for name in iface.names():
        if name not in dir(candidate):
            errors.append(f"Candidate is missing required attribute or method: {name}")
            continue

        required_method = iface.get(name)
        if callable(required_method):
            candidate_method = getattr(candidate, name)
            if not callable(candidate_method):
                errors.append(f"Attribute {name} is required to be a method")
                continue

            required_signature = inspect.signature(required_method)
            candidate_signature = inspect.signature(candidate_method)
            if candidate_signature != required_signature:
                errors.append(f"Method {name} has incorrect signature. Expected: {required_signature}, got: {candidate_signature}")

    if errors:
        if len(errors) == 1:
            raise zope.interface.Invalid(errors[0])
        else:
            raise zope.interface.Invalid(", ".join(errors))

    return True

