def find_tags(text: str, replacer: callable = None) -> Tuple[Set, str]:
    tags = set()
    in_code_block = False
    result_text = []
    i = 0
    while i < len(text):
        if text[i:i+3] == '```':
            in_code_block = not in_code_block
            result_text.append(text[i:i+3])
            i += 3
        elif text[i] == '#' and not in_code_block:
            tag_start = i
            i += 1
            while i < len(text) and text[i].isalnum():
                i += 1
            tag = text[tag_start:i]
            tags.add(tag)
            if replacer:
                result_text.append(replacer(tag))
            else:
                result_text.append(tag)
        else:
            result_text.append(text[i])
            i += 1
    return tags, ''.join(result_text)

