def parse_diaspora_webfinger(document: str) -> Dict:
    if document.startswith('{'):
        import json
        return json.loads(document)
    else:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(document)
        result = {}
        for elem in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Alias'):
            result['alias'] = elem.text
        for elem in root.findall('.//{http://docs.oasis-open.org/ns/xri/xrd-1.0}Link'):
            link = {}
            for attr, value in elem.attrib.items():
                link[attr] = value
            rel = link.get('rel')
            if rel:
                result[rel] = link
        return result

